    text-align: center;
    max-width: 80px;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 3px;
    background: #dee2e6;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

/* Form Sections */
