/* Buttons */
.form-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e9ecef;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s;
    text-decoration: none;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-success {
    background: #198754;
    color: white;
}

.btn-success:hover:not(:disabled) {
    background: #157347;
}

.btn-outline {
    background: white;
    color: #6c757d;
    border: 1px solid #ced4da;
}

.btn-outline:hover {
    background: #f8f9fa;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-lg {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

.btn-link {
    background: none;
    color: #0d6efd;
    padding: 0;
    text-decoration: underline;
}

.btn-link:hover {
    color: #0b5ed7;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #495057;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
}

.character-count {
    text-align: right;
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #6c757d;
}

.character-count.warning {
    color: #dc3545;
    font-weight: 600;
}

/* Alert */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.alert-danger {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Review Section */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #6c757d;
}

.review-data dd {
    margin: 0;
    color: #212529;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #e9ecef;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.9rem;
    color: #6c757d;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #212529;
    line-height: 1.6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #198754;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.confirmation h3 {
    color: #198754;
    margin-bottom: 1rem;
}

.confirmation p {
    color: #6c757d;
    font-size: 1.1rem;
}
"}

