namespace sv_b5540578c5c343d6bafac5ce3748dc71.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_b5540578c5c343d6bafac5ce3748dc71.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <nav class="step-indicator" aria-label="Application steps">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)" role="button" tabindex="0">
                <div class="step-circle">
                    @if (stepIndex < _currentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <span class="step-label">@_stepNames[stepIndex]</span>
            </div>
            @if (i < _stepNames.Length - 1)
            {
                <div class="step-connector @(i < _currentStep ? "completed" : "")"></div>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger" role="alert">@_errorMessage</div>
    }

    @* Step 1: Personal Info *@
    @if (_currentStep == 0)
    {
        <section class="form-section">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" class="form-control" @bind="_fullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" class="form-control" @bind="_email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" class="form-control" @bind="_phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" class="form-control" @bind="_address" placeholder="Enter your address" />
            </div>
            <div class="form-buttons">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span>Validating...</span>
                    }
                    else
                    {
                        <span>Next</span>
                    }
                </button>
            </div>
        </section>
    }

    @* Step 2: Work History *@
    @if (_currentStep == 1)
    {
        <section class="form-section">
            <h2>Work History</h2>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" class="form-control" @bind="_workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" class="form-control" @bind="_workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" class="form-control" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group form-check">
                        <input type="checkbox" class="form-check-input" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                        <label class="form-check-label" for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea class="form-control" @bind="_workEntries[index].Description" rows="3" placeholder="Describe your responsibilities"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-buttons">
                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </section>
    }

    @* Step 3: References *@
    @if (_currentStep == 2)
    {
        <section class="form-section">
            <h2>References</h2>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (_references.Count > 2)
                        {
                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" class="form-control" @bind="_references[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" class="form-control" @bind="_references[index].Relationship" placeholder="e.g., Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" class="form-control" @bind="_references[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" class="form-control" @bind="_references[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-buttons">
                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
    }

    @* Step 4: Cover Letter *@
    @if (_currentStep == 3)
    {
        <section class="form-section">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter *</label>
                <textarea id="coverLetter" class="form-control cover-letter-textarea" @bind="_coverLetter" @bind:event="oninput" rows="12" maxlength="2000" placeholder="Tell us why you're a great fit for this position..."></textarea>
                <div class="character-count @(_coverLetter.Length > 1800 ? "warning" : "")">
                    @_coverLetter.Length / 2000 characters
                </div>
            </div>
            <div class="form-buttons">
                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </section>
    }

    @* Step 5: Review & Submit *@
    @if (_currentStep == 4)
    {
        <section class="form-section">
            <h2>Review & Submit</h2>

            @if (_isSubmitted)
            {
                <div class="confirmation">
                    <div class="confirmation-icon">&#10003;</div>
                    <h3>Application Submitted Successfully!</h3>
                    <p>Your application ID is: <strong>@_applicationId</strong></p>
                    <p>We'll be in touch soon. Thank you for applying!</p>
                </div>
            }
            else
            {
                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl class="review-data">
                        <dt>Full Name</dt><dd>@_fullName</dd>
                        <dt>Email</dt><dd>@_email</dd>
                        <dt>Phone</dt><dd>@_phone</dd>
                        <dt>Address</dt><dd>@_address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                            <br />
                            <span class="review-dates">@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                            <p>@entry.Description</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in _references)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)
                            <br />
                            <span>@reference.Email | @reference.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="review-cover-letter">@_coverLetter</p>
                </div>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            }
        </section>
    }
</div>

@code {
    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int _currentStep = 0;
    private string _errorMessage = string.Empty;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _isSubmitted;
    private int _applicationId;

    // Step 1: Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string _coverLetter = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == _currentStep) return "active";
        if (stepIndex < _currentStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValidEmail)
            {
                _errorMessage = "The email address is not valid. Please enter a valid email.";
                return;
            }
            _currentStep = 1;
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = string.Empty;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
            {
                _errorMessage = "Please fill in all required fields for each work entry.";
                return;
            }
        }

        _currentStep = 2;
    }

    private void NextFromReferences()
    {
        _errorMessage = string.Empty;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                _errorMessage = "Please fill in all required fields for each reference.";
                return;
            }
        }

        _currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }

        _currentStep = 4;
    }

    private void PreviousStep()
    {
        _errorMessage = string.Empty;
        if (_currentStep > 0)
            _currentStep--;
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workEntries = _workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
            var work = new WorkHistory(workEntries);
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, work, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _isSubmitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

